249	        char4 pixlabels = tex2D(multilabelTex, u ,v);
250	        char* bob = (char*)&pixlabels; //horrible but char4's have xyzw members
251	        for(int ti = 0; ti < numTrees; ++ti)
252	          bins[ bob[ti] ]++;        
253	      }
254	
255	      int res = findMaxId_testTie(NUM_LABELS, bins);
256	
257	      // if this fails... find a consensus in a 1 neighbourhood
258	      if( res < 0 ) 
259	      {
260	        int depth = tex2D(depthTex, u,v);
261	        for(int i = -1 ; i <= 1; ++i) 
262	        {
263	          for(int j = -1; j <= 1; ++j) 
264	          {
265	            int   depth_neighbor  = tex2D(depthTex,u+i,v+j);
266	            char4 labels_neighbor = tex2D(multilabelTex, u+i,v+j); 
267	            char* bob = (char*)&labels_neighbor; //horrible but char4's have xyzw members
268	            //TODO: redo this part
269	            int weight = std::abs(depth-depth_neighbor) < 50 ? 1:0; // 5cms
270	            for(int ti = 0; ti < numTrees; ++ti)
271	              bins[ bob[ti] ] += weight;
272	          }
273	        }
274	        res = findMaxId( NUM_LABELS, bins );
275	      }      
276	      labels.ptr(v)[u] = res;
277	    }
