279	    /** \brief This merges the labels from all trees into a histogram of probabilities **/
280	    __global__ void KernelCUDA_MultiTreeCreateProb (const int numTrees, PtrStepSz<prob_histogram> prob)
281	    {
282	      // map block and thread onto image coordinates
283	      int u = blockIdx.x * blockDim.x + threadIdx.x;
284	      int v = blockIdx.y * blockDim.y + threadIdx.y;
285	
286	      if( u >= prob.cols || v >= prob.rows )
287	        return;
288	
289	      char4 pixlabels = tex2D (multilabelTex, u ,v);
290	      char* bob = (char*)&pixlabels; //horrible but char4's have xyzw members
291	
292	      // Reset prob first, this should become NUM_LABELS
293	      for(int in = 0; in < NUM_LABELS; in++)
294	      {
295	        prob.ptr(v)[u].probs[in] = 0;
296	      }
297	
298	      for(int ti = 0; ti < numTrees; ++ti)
299	      {
300	        // Each tree casts a vote to the probability
301	        // TODO: replace this with a histogram copy
302	        prob.ptr(v)[u].probs[bob[ti]] += 0.25;
303	      }
304	    }
